using System.IO;
using System.Linq;
using ProjectTower.config;
using ProjectTower.player;

namespace SkillTreeEdit.skilltree;

public class SkillTree
{
	public static SkillImg[] imgs;

	public static SkillNode[] nodes;

	public static SkillNode[] enhancedNodes;

	public static SkillNode[] classicNodes;

	public static void Init()
	{
		ReadTree();
	}

	public static void ReadTree()
	{
		BinaryReader binaryReader = new BinaryReader(File.Open("skilltree/data/classic/skilltree.zsx", FileMode.Open, FileAccess.Read));
		Read(binaryReader);
		binaryReader.Close();
		BinaryReader binaryReader2 = new BinaryReader(File.Open("skilltree/data/enhanced/skilltree.zsx", FileMode.Open, FileAccess.Read));
		Read(binaryReader2, isEnhanced: true);
		binaryReader2.Close();
	}

	internal static void Read(BinaryReader reader, bool isEnhanced = false)
	{
		int num = reader.ReadInt32();
		nodes = new SkillNode[num];
		if (isEnhanced)
		{
			enhancedNodes = new SkillNode[num];
		}
		else
		{
			classicNodes = new SkillNode[num];
		}
		for (int i = 0; i < num; i++)
		{
			if (isEnhanced)
			{
				nodes[i] = (enhancedNodes[i] = new SkillNode(reader, i));
			}
			else
			{
				nodes[i] = (classicNodes[i] = new SkillNode(reader, i));
			}
		}
		if (!isEnhanced)
		{
			num = reader.ReadInt32();
			imgs = new SkillImg[num];
			for (int j = 0; j < num; j++)
			{
				imgs[j] = new SkillImg(reader);
			}
		}
	}

	public static bool GetCanUnlock(SkillNode node, PlayerStats pStats, bool hasUnlocks)
	{
		int num = 16;
		bool flag = false;
		if (pStats.classUnlocks[0] == -1 && pStats.classUnlocks[1] == -1 && node.ID == num && !hasUnlocks)
		{
			flag = true;
		}
		else if (pStats.classUnlocks[0] != node.ID && pStats.classUnlocks[1] != node.ID && pStats.treeUnlocks[node.ID] > 0)
		{
			flag = true;
		}
		else
		{
			for (int i = 0; i < 2; i++)
			{
				if (node.parent[i] > -1 && (pStats.treeUnlocks[node.parent[i]] > 0 || pStats.classUnlocks[0] == node.parent[i] || pStats.classUnlocks[1] == node.parent[i]))
				{
					flag = true;
				}
			}
			if (!flag)
			{
				for (int j = 0; j < nodes.Length; j++)
				{
					if (pStats.treeUnlocks[j] <= 0 && pStats.classUnlocks[0] != j && pStats.classUnlocks[1] != j)
					{
						continue;
					}
					for (int k = 0; k < 2; k++)
					{
						if (nodes[j].parent[k] == node.ID)
						{
							flag = true;
							break;
						}
					}
					if (flag)
					{
						break;
					}
				}
			}
			if (flag)
			{
				int type = node.type;
				if ((uint)type <= 16u || (uint)(type - 25) <= 3u)
				{
					if (GameModeMgr.IsGameEnhanced())
					{
						bool num2 = node.value == 3 && pStats.itemClass[node.type] == 4;
						bool flag2 = node.value == 2 && node.title[0].Contains('4') && pStats.itemClass[node.type] == 3;
						bool flag3 = node.value == 2 && node.title[0].Contains('3') && pStats.itemClass[node.type] == 2;
						bool flag4 = node.value == 1 && node.title[0].Contains('2') && pStats.itemClass[node.type] == 1;
						bool flag5 = node.value == 1 && node.title[0].Contains('1') && pStats.itemClass[node.type] == 0;
						if (!(num2 | flag2 | flag3 | flag4 | flag5))
						{
							flag = false;
						}
					}
					else if (pStats.itemClass[node.type] < node.value - 1)
					{
						flag = false;
					}
				}
			}
		}
		return flag;
	}
}
